<script lang="ts">
 import shape from '#lib/geo/germany.json';import places from '#lib/geo/places.json';
 let{slug,compact=false}:{slug:string;compact?:boolean}=$props();const place=$derived(places[slug as keyof typeof places]);const x=$derived(place?(place.lon-5.5)*24:0);const y=$derived(place?(55.5-place.lat)*38:0);
</script>
{#if place}<div class="region-location" class:compact><svg viewBox="0 0 280 335" role="img" aria-label={'Deutschlandkarte mit '+place.town+' als Bezugspunkt'}><path d={shape.path} class="germany-outline"/>{#if !compact}<path d={'M'+x+','+y+'H250'} class="map-locator-line"/>{/if}<circle cx={x} cy={y} r="12" class="map-halo"/><circle cx={x} cy={y} r="4" class="map-point"/>{#if !compact}<text x="250" y={y-10} text-anchor="end" class="map-town-label">{place.town}</text>{/if}</svg>{#if !compact}<div class="location-copy"><span class="eyebrow">LAGE IN DEUTSCHLAND</span><h4>{place.town}</h4><p>{slug==='saar'?'Ayl liegt an der unteren Saar in Rheinland-Pfalz. Der Weinbaubereich Saar gehört zum Anbaugebiet Mosel.':slug==='rheinhessen'?'In Alsheim sitzt JUWEL. Rheinhessen liegt links des Rheins in Rheinland-Pfalz.':slug==='pfalz'?'In Deidesheim sitzt von Winning. Der Ort liegt an der Mittelhaardt in der Pfalz.':'Ein Bezugspunkt im Anbaugebiet. Die Weinberge verteilen sich auch auf weitere Orte und Standorte.'}</p><small>Der Punkt markiert den Ort, keine Grenze des Anbaugebiets.</small></div>{/if}</div>{/if}
